-- Seed order + rating_reviews (lalu hitung ulang rating merchant). Idempoten.
begin;
select setval(pg_get_serial_sequence('public.addresses','id'), greatest((select coalesce(max(id),0) from public.addresses), 7));
select setval(pg_get_serial_sequence('public.orders','id'), greatest((select coalesce(max(id),0) from public.orders), 70));
select setval(pg_get_serial_sequence('public.rating_reviews','id'), greatest((select coalesce(max(id),0) from public.rating_reviews), 93));
update public.merchants m set rating_avg = coalesce(a.avg, 0), rating_count = coalesce(a.cnt, 0) from (select merchant_id, round(avg(rating)::numeric, 2) as avg, count(*) as cnt from public.rating_reviews where merchant_id is not null group by merchant_id) a where m.id = a.merchant_id;
commit;